export default class Player {
  constructor(scene, x, y, bulletsGroup) {
    this.scene = scene;
    this.bullets = bulletsGroup;

    // ======================
    // SPRITE
    // ======================
    this.sprite = scene.physics.add.sprite(x, y, "player");
    this.sprite.setCollideWorldBounds(true);

    // ======================
    // INPUT
    // ======================
    this.cursors = scene.input.keyboard.createCursorKeys();

    // ======================
    // RECOIL / CHARGE SETTINGS
    // ======================
    this.isCharging = false;
    this.charge = 0;

    this.chargeTimeMs = 700;     // time to full charge
    this.minRecoil = 220;        // weakest jump
    this.maxRecoil = 850;        // strongest jump

    this.bulletBaseSpeed = 500;
    this.bulletExtraSpeed = 900;

    // ======================
    // MOUSE INPUT
    // ======================
    scene.input.on("pointerdown", () => {
      // Only charge when grounded (Jump King feel)
      if (this.sprite.body.blocked.down) {
        this.isCharging = true;
        this.charge = 0;
        this.sprite.setVelocity(0, 0);
      }
    });

    scene.input.on("pointerup", () => {
      if (!this.isCharging) return;
      this.isCharging = false;
      this.fireChargedShot();
    });
  }

  // ======================
  // UPDATE LOOP
  // ======================
  update() {
    // While charging, build power and lock movement
    if (this.isCharging) {
      const dt = this.scene.game.loop.delta;
      this.charge = Phaser.Math.Clamp(
        this.charge + dt / this.chargeTimeMs,
        0,
        1
      );

      // Lock movement for precision
      this.sprite.setVelocityX(0);
      return;
    }

    // Optional air control (very small, Jump King style)
    if (!this.sprite.body.blocked.down) {
      if (this.cursors.left.isDown) {
        this.sprite.setVelocityX(-60);
      } else if (this.cursors.right.isDown) {
        this.sprite.setVelocityX(60);
      }
    }
  }

  // ======================
  // CHARGED SHOT + RECOIL
  // ======================
  fireChargedShot() {
    if (!this.bullets) return;

    // Strength from charge
    const recoilPower = Phaser.Math.Linear(
      this.minRecoil,
      this.maxRecoil,
      this.charge
    );

    const bulletSpeed =
      this.bulletBaseSpeed + this.bulletExtraSpeed * this.charge;

    // Mouse aim (WORLD coordinates – camera safe)
    const pointer = this.scene.input.activePointer;
    let dx = pointer.worldX - this.sprite.x;
    let dy = pointer.worldY - this.sprite.y;

    // Normalize direction
    const len = Math.hypot(dx, dy) || 1;
    dx /= len;
    dy /= len;

    // ======================
    // BULLET
    // ======================
    const bullet = this.bullets.get(
      this.sprite.x + dx * 20,
      this.sprite.y + dy * 20,
      "bullet"
    );

    if (bullet) {
      bullet.setActive(true);
      bullet.setVisible(true);
      bullet.body.enable = true;
      bullet.body.allowGravity = false;

      bullet.setVelocity(dx * bulletSpeed, dy * bulletSpeed);

      // Recycle bullet
      bullet.update = () => {
        const b = this.scene.physics.world.bounds;
        if (
          bullet.x < b.x - 100 ||
          bullet.x > b.right + 100 ||
          bullet.y < b.y - 100 ||
          bullet.y > b.bottom + 100
        ) {
          this.bullets.killAndHide(bullet);
          bullet.body.enable = false;
        }
      };
    }

    // ======================
    // RECOIL (THIS IS THE JUMP)
    // ======================
    this.sprite.setVelocity(
      -dx * recoilPower,
      -dy * recoilPower
    );
  }
}
